insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0889','economics','Markets','easy','classic','What is a service in economics?','["An activity or benefit provided rather than a physical good","A natural resource before extraction","A tax refunded to a company","A unit used to measure inflation"]'::jsonb,'An activity or benefit provided rather than a physical good','Services are economic activities or benefits that are generally intangible rather than physical goods.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
