insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0891','economics','Banking','medium','classic','What is a central bank commonly responsible for?','["Conducting monetary policy and supporting the financial system","Setting the menu prices of restaurants","Issuing every private company''s shares","Choosing the winners of national elections"]'::jsonb,'Conducting monetary policy and supporting the financial system','Central banks commonly conduct monetary policy and support financial and payment-system stability.',10,2,array['banking'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0892','economics','Banking','easy','classic','What is interest on a loan?','["The cost paid for borrowing money","A tax paid only on imported fruit","The number of bank branches in a city","A reward that cancels the original debt"]'::jsonb,'The cost paid for borrowing money','Interest is the charge for borrowing money, usually expressed as a rate over time.',10,2,array['banking'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0893','economics','Banking','medium','classic','What is compound interest?','["Interest calculated on principal and previously accumulated interest","Interest paid only once on a loan''s final day","A tax on every cash purchase","A fee for exchanging paper money"]'::jsonb,'Interest calculated on principal and previously accumulated interest','With compound interest, interest is earned or charged on the principal and on prior accumulated interest.',10,2,array['banking'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0894','economics','Markets','medium','classic','What is a negative externality?','["A cost imposed on people not directly involved in a transaction","A discount given to every buyer","A benefit that belongs only to the producer","A change in the spelling of a price"]'::jsonb,'A cost imposed on people not directly involved in a transaction','A negative externality is a cost borne by a third party, such as pollution affecting nearby residents.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0895','economics','Markets','medium','classic','In economics, what is a monopoly?','["A market dominated by one seller with no close substitute","A market with thousands of identical sellers","A government budget with no taxes","A store that accepts only coins"]'::jsonb,'A market dominated by one seller with no close substitute','A monopoly is a market structure in which one seller has substantial control and buyers lack close alternatives.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0896','economics','Markets','medium','classic','What does comparative advantage depend on?','["A lower opportunity cost of producing something","Having the largest population","Charging the highest possible price","Producing every good with no resources"]'::jsonb,'A lower opportunity cost of producing something','Comparative advantage arises when a producer can make a good at a lower opportunity cost than another producer.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
