insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0996','management','Project delivery','medium','classic','What is a project baseline?','["An approved reference plan used to compare actual progress","A list of every possible supplier","The final invoice from a contractor","A type of team-building exercise"]'::jsonb,'An approved reference plan used to compare actual progress','A baseline is an approved plan or set of measures against which project performance can be compared.',10,2,array['project delivery'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0997','management','Risk','medium','classic','What does risk mitigation aim to do?','["Reduce the likelihood or impact of a risk","Guarantee that no uncertain event can occur","Transfer every task to a customer","Increase the project''s uncertainty"]'::jsonb,'Reduce the likelihood or impact of a risk','Risk mitigation selects actions intended to lower a risk''s probability or consequences.',10,2,array['risk'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-0998','management','Quality','medium','classic','What is quality assurance mainly concerned with?','["Processes intended to help meet quality requirements","Counting only products that failed","Choosing the company''s logo","Setting the selling price of every product"]'::jsonb,'Processes intended to help meet quality requirements','Quality assurance focuses on the processes used to provide confidence that quality requirements will be met.',10,2,array['quality'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
