insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1003','management','Change management','medium','classic','What is a change impact assessment used to consider?','["How a proposed change may affect people, processes, and systems","The weather during a project launch","Only the font in a presentation","Whether every employee can use the same desk"]'::jsonb,'How a proposed change may affect people, processes, and systems','A change impact assessment identifies affected groups and possible operational consequences of a proposed change.',10,2,array['change management'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
