insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1009','business','Finance','medium','classic','What is a variable cost?','["A cost that changes with the level of activity or output","A cost that is always zero","A permanent business name","A tax charged only on profit"]'::jsonb,'A cost that changes with the level of activity or output','Variable costs tend to increase or decrease as production or sales activity changes.',10,2,array['finance'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
