insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1018','business','Finance','medium','classic','What does gross margin compare?','["Revenue remaining after cost of goods sold, relative to revenue","Cash in a bank account and cash in a drawer","The number of customers and the number of suppliers","Interest paid and taxes collected"]'::jsonb,'Revenue remaining after cost of goods sold, relative to revenue','Gross margin is commonly calculated as revenue minus cost of goods sold, divided by revenue.',10,2,array['finance'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
