insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1020','business','Operations','medium','classic','What is a value chain?','["Activities through which a business creates and delivers value","A list of every company on a stock exchange","A delivery route with no stops","A chain used to secure a warehouse door"]'::jsonb,'Activities through which a business creates and delivers value','A value chain examines linked activities that contribute to creating, delivering, and supporting a product or service.',10,2,array['operations'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
