insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1030','accounting','Controls','medium','classic','What is a bank reconciliation?','["A comparison of accounting cash records with a bank statement","A method for calculating employee vacations","A list of customers who have paid in coins","A budget for opening a new bank"]'::jsonb,'A comparison of accounting cash records with a bank statement','A bank reconciliation identifies and explains differences between an entity''s cash records and the bank''s records.',10,2,array['controls'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1031','accounting','Statements','medium','classic','What does a cash flow statement summarize?','["Cash inflows and outflows over a reporting period","Only the value of buildings on one date","The number of products in a warehouse","The personal spending of every employee"]'::jsonb,'Cash inflows and outflows over a reporting period','A cash flow statement reports cash flows, commonly classified as operating, investing, and financing activities.',10,2,array['statements'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1032','accounting','Equity','medium','classic','What are retained earnings?','["Accumulated profits kept in the business, less distributions and other adjustments","Amounts customers still owe","Cash borrowed from a supplier","The cost of every product sold in one day"]'::jsonb,'Accumulated profits kept in the business, less distributions and other adjustments','Retained earnings represent accumulated net income retained in equity, adjusted for distributions and other items.',10,2,array['equity'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1033','accounting','Entries','medium','classic','What are closing entries used for at the end of an accounting period?','["Transfer temporary account balances into permanent accounts","Record the opening hours of a shop","Change every asset into cash","Reconcile a company''s logo with its trademark"]'::jsonb,'Transfer temporary account balances into permanent accounts','Closing entries reset temporary revenue and expense accounts and transfer their net result to equity.',10,2,array['entries'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1034','accounting','Accruals','medium','classic','What is a prepaid expense?','["A payment made before the related benefit is consumed","A bill received after a service is used","A cash sale that has not occurred","A loan that has been forgiven"]'::jsonb,'A payment made before the related benefit is consumed','A prepaid expense is initially recorded as an asset when payment precedes the related use or benefit.',10,2,array['accruals'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1035','accounting','Accruals','medium','classic','What is an accrued expense?','["A cost recognized before it has been paid","A customer payment received before a sale","A product returned to a supplier","A long-term investment that earns a dividend"]'::jsonb,'A cost recognized before it has been paid','An accrued expense is recognized when incurred even though payment will occur later.',10,2,array['accruals'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1036','accounting','Inventory','medium','classic','What does FIFO mean as an inventory cost-flow assumption?','["First in, first out","Final invoice, final order","Fixed interest, fixed output","Financial information for operations"]'::jsonb,'First in, first out','FIFO assumes that the earliest costs are assigned to goods sold first, subject to the applicable accounting framework.',10,2,array['inventory'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1037','accounting','Analysis','medium','classic','What is the current ratio commonly calculated as?','["Current assets divided by current liabilities","Revenue divided by long-term debt","Cash divided by yearly sales only","Profit divided by the number of employees"]'::jsonb,'Current assets divided by current liabilities','The current ratio is commonly calculated by dividing current assets by current liabilities.',10,2,array['analysis'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1038','accounting','Assets','medium','classic','What is goodwill in financial reporting commonly associated with?','["An acquired business''s value beyond identifiable net assets","A charitable donation recorded as inventory","A company''s daily cash register total","A guarantee that future profit is certain"]'::jsonb,'An acquired business''s value beyond identifiable net assets','Goodwill can arise in a business combination when consideration exceeds the fair value of identifiable net assets acquired.',10,2,array['assets'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1039','accounting','Assets','medium','classic','What is a capital expenditure?','["Spending to acquire or improve a long-term asset","A routine payment for a monthly phone bill","A cash refund from a customer","A dividend paid to a shareholder"]'::jsonb,'Spending to acquire or improve a long-term asset','Capital expenditure generally creates or improves a long-term asset rather than paying an ordinary period expense.',10,2,array['assets'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1040','accounting','Controls','medium','classic','What is an internal control in accounting?','["A process designed to support reliable reporting and safeguard resources","A tax rate set by another country","A marketing slogan printed on a receipt","A forecast that is guaranteed to be exact"]'::jsonb,'A process designed to support reliable reporting and safeguard resources','Internal controls help an organization address risks related to operations, reporting, and compliance.',10,2,array['controls'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1041','accounting','Statements','medium','classic','What is materiality in financial reporting?','["Whether information could influence users'' decisions","Whether a document is printed on heavy paper","Whether every account has a round balance","Whether a report contains photographs"]'::jsonb,'Whether information could influence users'' decisions','Information is material if omitting, misstating, or obscuring it could reasonably influence users'' decisions.',10,2,array['statements'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1042','accounting','Audit','medium','classic','What is audit evidence?','["Information used by an auditor to reach conclusions","A guarantee that a company will never fail","A list of all future sales","A receipt that must always be handwritten"]'::jsonb,'Information used by an auditor to reach conclusions','Audit evidence includes information used to support the auditor''s findings and opinion.',10,2,array['audit'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1043','accounting','Accruals','medium','classic','What is an allowance for doubtful accounts intended to estimate?','["Receivables that may not be collected","The number of new customers next year","The amount of cash in a petty-cash box","The cost of replacing every computer"]'::jsonb,'Receivables that may not be collected','An allowance estimates expected credit losses or uncollectible amounts on receivables under the applicable framework.',10,2,array['accruals'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1044','accounting','Reporting','medium','classic','What is an accounting period?','["A span of time covered by financial reports","The time between two bank branches","A rule that all invoices expire in one day","The number of entries in a single journal"]'::jsonb,'A span of time covered by financial reports','An accounting period is the interval for which financial results and position are reported.',10,2,array['reporting'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1045','accounting','Statements','medium','classic','What is an operating expense?','["A cost incurred in the ordinary activities of a business","The purchase price of a long-term building only","An owner''s personal household payment","A loan principal balance"]'::jsonb,'A cost incurred in the ordinary activities of a business','Operating expenses are costs of running the ordinary activities of a business, rather than direct capital purchases.',10,2,array['statements'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1046','accounting','Bookkeeping','medium','classic','Why are source documents such as invoices and receipts retained?','["They provide evidence supporting recorded transactions","They automatically calculate the company''s tax bill","They replace the general ledger","They guarantee that every customer will pay"]'::jsonb,'They provide evidence supporting recorded transactions','Source documents provide an audit trail and evidence for transactions entered into accounting records.',10,2,array['bookkeeping'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1047','commerce','Documents','medium','classic','What is a purchase order?','["A buyer''s formal request to purchase specified goods or services","A seller''s proof that money has been received","A document that replaces all delivery records","A bank statement from a supplier"]'::jsonb,'A buyer''s formal request to purchase specified goods or services','A purchase order specifies what a buyer is requesting and the agreed purchasing details.',10,2,array['documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1048','commerce','Documents','medium','classic','What does a packing list usually describe?','["The contents and quantities in a shipment","The buyer''s annual tax return","The driver''s medical history","The seller''s advertising plan"]'::jsonb,'The contents and quantities in a shipment','A packing list itemizes the contents of a shipment to help with handling and checking delivery.',10,2,array['documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1049','commerce','Documents','medium','classic','What does a certificate of origin identify?','["The country where goods are considered to originate","The name of the final delivery driver","The temperature of a warehouse","The retail price in every destination market"]'::jsonb,'The country where goods are considered to originate','A certificate of origin states the country of origin of goods for trade or customs purposes.',10,2,array['documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1050','commerce','Payments','medium','classic','What is a letter of credit used for in international trade?','["A bank''s conditional undertaking to pay when stated documents are presented","A letter that guarantees every shipment arrives on time","A receipt proving a buyer has paid cash","A customs tax charged on all services"]'::jsonb,'A bank''s conditional undertaking to pay when stated documents are presented','A letter of credit is a bank commitment to pay a beneficiary if the required terms and documents are met.',10,2,array['payments'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1051','commerce','Logistics','medium','classic','What does a freight forwarder commonly arrange?','["Transportation and related logistics for a shipment","The design of a product''s logo","The buyer''s annual company audit","The sale of a business''s shares"]'::jsonb,'Transportation and related logistics for a shipment','A freight forwarder coordinates shipment arrangements and related logistics on behalf of a shipper.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1052','commerce','Logistics','medium','classic','What is last-mile delivery?','["The final leg of a delivery to its destination","The first step in manufacturing a product","A method for measuring warehouse temperature","The distance between two countries'' capitals"]'::jsonb,'The final leg of a delivery to its destination','Last-mile delivery is the final part of moving goods from a distribution point to the recipient.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1053','commerce','Logistics','medium','classic','What is reverse logistics?','["Moving goods back through a supply chain for return, repair, or recovery","Transporting goods only from a factory to a shop","A plan for reversing a truck in a driveway","A way to make every shipment travel twice as fast"]'::jsonb,'Moving goods back through a supply chain for return, repair, or recovery','Reverse logistics handles returns and the recovery, repair, recycling, or disposal of products and materials.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1054','commerce','Trade','medium','classic','What is a trade balance?','["The value of exports compared with the value of imports","The number of traders in a market","The cost of a country''s national flag","A list of all goods in a shop"]'::jsonb,'The value of exports compared with the value of imports','A trade balance compares a country''s exports and imports over a period.',10,2,array['trade'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1055','commerce','Payments','easy','classic','What does cash on delivery mean?','["Payment is collected when goods are delivered","Payment is made only after one year","Goods are delivered without any payment ever","The customer pays before placing an order"]'::jsonb,'Payment is collected when goods are delivered','Cash on delivery requires payment at the time goods are delivered, according to the seller''s terms.',10,2,array['payments'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1056','commerce','Warehousing','medium','classic','What is cycle counting in inventory management?','["Counting selected stock items on a rotating schedule","Counting every customer once a year","Measuring the circumference of a delivery route","Checking the age of a cash register"]'::jsonb,'Counting selected stock items on a rotating schedule','Cycle counting verifies portions of inventory on an ongoing schedule rather than counting everything at once.',10,2,array['warehousing'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1057','commerce','Trade','medium','classic','What is a customs declaration?','["Information submitted about goods crossing a border","A promise that an item can never be returned","A list of local shop opening hours","A shipping label with no description of contents"]'::jsonb,'Information submitted about goods crossing a border','A customs declaration provides details about goods being imported or exported for customs processing.',10,2,array['trade'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1058','commerce','Supply chains','medium','classic','What is a supply chain?','["The linked organizations and activities involved in providing a product","A chain used to secure a warehouse gate","A list of one company''s office supplies","A route used only for transporting letters"]'::jsonb,'The linked organizations and activities involved in providing a product','A supply chain connects organizations and processes involved in sourcing, making, moving, and delivering products.',10,2,array['supply chains'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1059','commerce','Documents','medium','classic','What is a bill of exchange?','["A written order directing one party to pay a stated amount","A receipt for goods already returned","A document showing a product''s color","A list of bank holidays"]'::jsonb,'A written order directing one party to pay a stated amount','A bill of exchange is a written instrument ordering a drawee to pay a specified sum under stated terms.',10,2,array['documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1060','commerce','Trade','medium','classic','What is a customs duty?','["A tax imposed on goods crossing a customs border","A fee paid to store a product at home","A discount given to a wholesale customer","A payment made to a delivery driver as a tip"]'::jsonb,'A tax imposed on goods crossing a customs border','A customs duty is a tax or charge imposed on certain imported or exported goods.',10,2,array['trade'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1061','commerce','Payments','medium','classic','What are payment terms in a commercial sale?','["The agreed timing and conditions for paying an invoice","The list of goods held by a carrier","The quality standards for a factory","A company''s annual staff schedule"]'::jsonb,'The agreed timing and conditions for paying an invoice','Payment terms state when and how a buyer is expected to pay an invoice.',10,2,array['payments'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1062','commerce','Retail','medium','classic','What is a point-of-sale system used to do?','["Process purchases and record sales at checkout","Make a product without any materials","Transport a shipment across an ocean","Decide the result of a court hearing"]'::jsonb,'Process purchases and record sales at checkout','A point-of-sale system supports checkout, payment processing, and recording sales transactions.',10,2,array['retail'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1063','commerce','Supply chains','medium','classic','What does traceability mean in a supply chain?','["The ability to follow a product''s history or movement","A guarantee that no product will ever be recalled","The speed at which a barcode is printed","The total amount of tax paid by every company"]'::jsonb,'The ability to follow a product''s history or movement','Traceability lets organizations track products, components, or materials through stages of a supply chain.',10,2,array['supply chains'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1064','commerce','Retail','easy','classic','What is a barcode commonly used for in commerce?','["Identifying an item so its data can be scanned","Encrypting a telephone conversation","Measuring the weight of a truck from space","Printing a legal contract automatically"]'::jsonb,'Identifying an item so its data can be scanned','Barcodes encode identifying data that can be read by a scanner at checkout or during inventory work.',10,2,array['retail'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1065','commerce','Trade','medium','classic','What is countertrade?','["A trade arrangement in which goods or services are exchanged partly or wholly for other goods or services","A sale made only at a retail counter","A method for counting imported products twice","A bank loan repaid only with coins"]'::jsonb,'A trade arrangement in which goods or services are exchanged partly or wholly for other goods or services','Countertrade links a purchase to an exchange of goods or services rather than relying solely on cash payment.',10,2,array['trade'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1066','commerce','Logistics','medium','classic','What is a cold chain?','["A temperature-controlled supply chain for sensitive goods","A chain made only of frozen metal","A route used only during winter","A system for cooling shop lights"]'::jsonb,'A temperature-controlled supply chain for sensitive goods','A cold chain maintains required temperature conditions as products such as food or medicines are stored and transported.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1067','mathematics','Number sense','easy','classic','What is a prime number?','["A whole number greater than 1 with exactly two positive factors","A whole number that is divisible by every number","Any number with a decimal part","A number that has no factors"]'::jsonb,'A whole number greater than 1 with exactly two positive factors','A prime number has exactly two positive divisors: 1 and itself.',10,2,array['number sense'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1068','mathematics','Number sense','easy','classic','What is the least common multiple of two or more numbers?','["The smallest positive number that is a multiple of all of them","The largest number that divides only one of them","The sum of all their digits","The first number in a multiplication table"]'::jsonb,'The smallest positive number that is a multiple of all of them','The least common multiple is the smallest positive integer divisible by each number in the set.',10,2,array['number sense'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1069','mathematics','Number sense','easy','classic','What is the greatest common factor of two whole numbers?','["The largest positive integer that divides both numbers","The smallest positive number in either set","The sum of their squares","A number that is larger than both"]'::jsonb,'The largest positive integer that divides both numbers','The greatest common factor is the largest positive integer that divides each of the given integers.',10,2,array['number sense'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1070','mathematics','Geometry','easy','classic','What is the sum of the interior angles of a triangle in Euclidean geometry?','["180 degrees","90 degrees","270 degrees","360 degrees"]'::jsonb,'180 degrees','The three interior angles of a triangle in flat Euclidean geometry sum to 180 degrees.',10,2,array['geometry'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1071','mathematics','Geometry','easy','classic','What is the area of a square with side length s?','["s squared","4s","2s","s divided by 4"]'::jsonb,'s squared','A square''s area is its side length multiplied by itself, written s squared.',10,2,array['geometry'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1072','mathematics','Geometry','medium','classic','What is the circumference of a circle with radius r?','["2 pi r","pi r squared","r divided by 2 pi","4 pi r squared"]'::jsonb,'2 pi r','A circle''s circumference is 2 pi times its radius, or pi times its diameter.',10,2,array['geometry'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1073','mathematics','Number sense','easy','classic','What does percent mean?','["Per one hundred","Per one thousand","Per ten","Per one million"]'::jsonb,'Per one hundred','Percent means per hundred; for example, 25 percent is 25 out of 100.',10,2,array['number sense'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1074','mathematics','Fractions','easy','classic','In the fraction 5 over 8, what is the denominator?','["8","5","13","40"]'::jsonb,'8','The denominator is the bottom number of a fraction; it names the number of equal parts in the whole.',10,2,array['fractions'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1075','mathematics','Fractions','easy','classic','What is the absolute value of negative 7?','["7","Negative 7","0","14"]'::jsonb,'7','Absolute value is distance from zero on the number line, so the absolute value of negative 7 is 7.',10,2,array['fractions'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1076','mathematics','Statistics','medium','classic','How is the median of a data set found?','["Sort the values and find the middle value","Add the largest and smallest values only","Choose the value that occurs most often","Multiply every value by the number of values"]'::jsonb,'Sort the values and find the middle value','The median is the middle value after the data are arranged in order; for an even count, it is the mean of the two middle values.',10,2,array['statistics'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1077','mathematics','Statistics','easy','classic','What is the mode of a data set?','["The value or values that occur most often","The difference between the largest and smallest values","The sum of all values divided by two","The middle value after sorting"]'::jsonb,'The value or values that occur most often','The mode is the value or values with the greatest frequency in a data set.',10,2,array['statistics'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1078','mathematics','Statistics','easy','classic','How is the arithmetic mean calculated?','["Add the values and divide by how many values there are","Subtract the smallest value from the largest","Select the value in the middle","Multiply the values together"]'::jsonb,'Add the values and divide by how many values there are','The arithmetic mean is the sum of the observations divided by the number of observations.',10,2,array['statistics'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
