insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1143','food','Food safety','medium','classic','What is cross-contamination in food handling?','["Transfer of harmful microbes from one food or surface to another","A method for adding flavor with herbs","A way to measure the weight of a recipe","A cooking technique that uses two ovens"]'::jsonb,'Transfer of harmful microbes from one food or surface to another','Cross-contamination happens when microbes or allergens are unintentionally transferred between foods, hands, or surfaces.',10,2,array['food safety'],'en',true,'USDA Food Safety and Inspection Service — https://www.fsis.usda.gov/food-safety ; FoodSafety.gov — https://www.foodsafety.gov/ ; Encyclopaedia Britannica, Food — https://www.britannica.com/topic/food') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
