insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1160','arts','Color','medium','classic','In the traditional red-yellow-blue model used for mixing paint, which colors are treated as primary?','["Red, yellow, and blue","Cyan, magenta, and yellow","Orange, green, and violet","Black, white, and gray"]'::jsonb,'Red, yellow, and blue','The traditional RYB model treats red, yellow, and blue as primary paint colors; other color models use different primaries.',10,2,array['color'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
